spec.expr:
count by (instance, job, server_name) (
  node_cpu_seconds_total{
    mode="idle",
    instance=~"$instance",
    job=~"$job"
  }
)

100 - (
  avg by (instance, server_name) (
    rate(
      node_cpu_seconds_total{
        mode="idle",
        instance=~"$instance",
        job=~"$job"
      }[5m]
    )
  ) * 100
)

100 * (
  1 -
  node_filesystem_avail_bytes{
    mountpoint="/",
    fstype!~"tmpfs|overlay",
    instance=~"$instance", 
    job=~"$job"
  }
  /
  node_filesystem_size_bytes{
    mountpoint="/",
    fstype!~"tmpfs|overlay",
    instance=~"$instance",
    job=~"$job"
  }
)

node_load1{
  instance=~"$instance",
  job=~"$job"
}
/
on(instance, job, server_name)
count by (instance, job, server_name) (
  node_cpu_seconds_total{
    mode="idle",
    instance=~"$instance",
    job=~"$job"
  }
)
